H,W=28,19
grid=[[0]*W for _ in range(H)]
objs={4:[(4,0),(4,1),(5,1),(6,1),(7,1),(9,4)],8:[(5,8)]+[(r,c) for r in (6,7,8) for c in (5,6,7)]+[(9,4)],9:[(11,c) for c in range(11,16)]+[(12,13),(13,13)],6:[(17,4),(18,4),(19,2),(19,3),(19,4),(20,4),(21,4)]}
deltas={4:-4,8:-5,9:14,6:6}
for color,pts in objs.items():
 for r,c in pts:
  rr=r+deltas[color]
  assert 0<=rr<H and grid[rr][c]==0, (color,rr,c,grid[rr][c])
  grid[rr][c]=color
print('\n'.join(' '.join(map(str,row)) for row in grid))

grid3=[[0]*19 for _ in range(28)]
d3={4:18,8:-5,9:14,6:-17}
for color,pts in objs.items():
 for r,c in pts:
  rr=r+d3[color]
  assert 0<=rr<28 and grid3[rr][c]==0,(color,rr,c)
  grid3[rr][c]=color
print('\n'.join(' '.join(map(str,row)) for row in grid3))
